INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (1, 2, 1, 'Selecciona los componentes de integración de un equipo microinformático estándar, describiendo sus funciones y comparando prestaciones de distintos fabricantes.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (2, 2, 2, 'Ensambla un equipo microinformático, interpretando planos e instrucciones del fabricante aplicando técnicas de montaje.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (3, 2, 3, 'Mide parámetros eléctricos, identificando el tipo de señal y relacionándola con sus unidades características.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (4, 2, 4, 'Mantiene equipos informáticos interpretando las recomendaciones de los fabricantes y relacionando las disfunciones con sus causas.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (5, 2, 5, 'Instala software en un equipo informático utilizando una imagen almacenada en un soporte de memoria y justificando el procedimiento a seguir.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (6, 2, 6, 'Reconoce nuevas tendencias en el ensamblaje de equipos microinformáticos describiendo sus ventajas y adaptándolas a las características de uso de los equipos.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (7, 2, 7, 'Mantiene periféricos, interpretando las recomendaciones de los fabricantes de equipos y relacionando disfunciones con sus causas.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (8, 2, 8, 'Cumple las normas de prevención de riesgos laborales y de protección ambiental, identificando los riesgos asociados, las medidas y equipos para prevenirlos.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (9, 4, 1, 'Reconoce las características de los sistemas de archivo, describiendo sus tipos y aplicaciones.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (10, 4, 2, 'Instala sistemas operativos, relacionando sus características con el hardware del equipo y el software de aplicación.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (11, 4, 3, 'Realiza tareas básicas de configuración de sistemas operativos, interpretando requerimientos y describiendo los procedimientos seguidos.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (12, 4, 4, 'Realiza operaciones básicas de administración de sistemas operativos, interpretando requerimientos y optimizando el sistema para su uso.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (13, 4, 5, 'Crea máquinas virtuales identificando su campo de aplicación e instalando software específico.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (101, 1, 1, 'Instala y actualiza aplicaciones ofimáticas, interpretando especificaciones y describiendo los pasos a seguir en el proceso.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (102, 1, 2, 'Elabora documentos y plantillas, describiendo y aplicando las opciones avanzadas de procesadores de textos.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (103, 1, 3, 'Elabora documentos y plantillas de cálculo, describiendo y aplicando opciones avanzadas de hojas de cálculo.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (104, 1, 4, 'Elabora documentos con bases de datos ofimáticas describiendo y aplicando operaciones de manipulación de datos.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (105, 1, 5, 'Manipula imágenes digitales analizando las posibilidades de distintos programas y aplicando técnicas de captura y edición básicas.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (106, 1, 6, 'Manipula secuencias de vídeo analizando las posibilidades de distintos programas y aplicando técnicas de captura y edición básicas.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (107, 1, 7, 'Elabora presentaciones multimedia describiendo y aplicando normas básicas de composición y diseño.');
INSERT INTO `resultados_aprendizaje` (`id_ra`, `id_modulo`, `numero`, `descripcion`) VALUES (108, 1, 8, 'Realiza operaciones de gestión del correo y la agenda electrónica, relacionando necesidades de uso con su configuración.');
