INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (1, 1, 'a', 'Se han descrito los bloques que componen un equipo microinformático y sus funciones.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (2, 1, 'b', 'Se ha reconocido la arquitectura de buses.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (3, 1, 'c', 'Se han descrito las características de los tipos de microprocesadores (frecuencia, tensiones, potencia, zócalos, entre otros).');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (4, 1, 'd', 'Se ha descrito la función de los disipadores y ventiladores.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (5, 1, 'e', 'Se han descrito las características y utilidades más importantes de la configuración de la placa base.');
