INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (10, 1, 'j', 'Se han identificado los elementos que acompañan a un componente de integración (documentación, controladores, cables y utilidades, entre otros).');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (11, 2, 'a', 'Se han seleccionado las herramientas y útiles necesarios para el ensamblado de equipos microinformáticos.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (12, 2, 'b', 'Se ha interpretado la documentación técnica de todos los componentes a ensamblar.');
