INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (14, 2, 'd', 'Se han ensamblado diferentes conjuntos de placa base, microprocesador y elementos de refrigeración en diferentes modelos de chasis, según las especificaciones dadas.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (15, 2, 'e', 'Se han ensamblado los módulos de memoria RAM, los discos fijos, las unidades de lectura / grabación en soportes de memoria auxiliar y otros componentes.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (16, 2, 'f', 'Se han configurado parámetros básicos del conjunto accediendo a la configuración de la placa base.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (17, 2, 'g', 'Se han ejecutado utilidades de chequeo y diagnóstico para verificar las prestaciones del conjunto ensamblado.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (18, 2, 'h', 'Se ha realizado un informe de montaje.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (19, 3, 'a', 'Se ha identificado el tipo de señal a medir con el aparato correspondiente.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (20, 3, 'b', 'Se ha seleccionado la magnitud, el rango de medida y se ha conectado el aparato según la magnitud a medir.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (21, 3, 'c', 'Se ha relacionado la medida obtenida con los valores típicos.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (22, 3, 'd', 'Se han identificado los bloques de una fuente de alimentación (F.A.) para un ordenador personal.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (23, 3, 'e', 'Se han enumerado las tensiones proporcionadas por una F.A. típica.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (24, 3, 'f', 'Se han medido las tensiones en F.A. típicas de ordenadores personales.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (25, 3, 'g', 'Se han identificado los bloques de un sistema de alimentación ininterrumpida.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (26, 3, 'h', 'Se han medido las señales en los puntos significativos de un SAI.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (27, 4, 'a', 'Se han reconocido las señales acústicas y/o visuales que avisan de problemas en el hardware de un equipo.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (28, 4, 'b', 'Se han identificado y solventado las averías producidas por sobrecalentamiento del microprocesador.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (29, 4, 'c', 'Se han identificado y solventado averías típicas de un equipo microinformático (mala conexión de componentes, incompatibilidades, problemas en discos fijos, suciedad, entre otras).');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (30, 4, 'd', 'Se han sustituido componentes deteriorados.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (31, 4, 'e', 'Se ha verificado la compatibilidad de los componentes sustituidos.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (32, 4, 'f', 'Se han realizado actualizaciones y ampliaciones de componentes.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (33, 4, 'g', 'Se han elaborado informes de avería (reparación o ampliación).');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (34, 5, 'a', 'Se ha reconocido la diferencia entre una instalación estándar y una preinstalación de software.');
