INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (36, 5, 'c', 'Se han inicializado equipos desde distintos soportes de memoria auxiliar.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (37, 5, 'd', 'Se han realizado imágenes de una preinstalación de software.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (38, 5, 'e', 'Se han restaurado imágenes sobre el disco fijo desde distintos soportes.');
