INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (40, 6, 'a', 'Se han reconocido las nuevas posibilidades para dar forma al conjunto chasis-placa base.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (41, 6, 'b', 'Se han descrito las prestaciones y características de algunas de las plataformas semiensambladas («barebones») más representativas del momento.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (42, 6, 'c', 'Se han descrito las características de los ordenadores de entretenimiento multimedia (HTPC), los chasis y componentes específicos empleados en su ensamblado.');
INSERT INTO `criterios_evaluacion` (`id_ce`, `id_ra`, `codigo`, `descripcion`) VALUES (43, 6, 'd', 'Se han descrito las características diferenciales que demandan los equipos informáticos empleados en otros campos de aplicación específicos.');
